@* A single Kanban column showing its header, task cards, and add-task form *@

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@ColumnName</strong>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body p-2" style="overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          OnMoveLeftClicked="HandleMoveLeft"
                          OnMoveRightClicked="HandleMoveRight" />
            }
            <AddTaskForm DefaultStatus="@ColumnName" OnTaskCreated="HandleTaskCreated" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(TaskItem Task, string Direction)> OnTaskMoved { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskRequest> OnTaskCreated { get; set; }

    private async Task HandleMoveLeft(TaskItem task) =>
        await OnTaskMoved.InvokeAsync((task, "left"));

    private async Task HandleMoveRight(TaskItem task) =>
        await OnTaskMoved.InvokeAsync((task, "right"));

    private async Task HandleTaskCreated(AddTaskForm.NewTaskRequest request) =>
        await OnTaskCreated.InvokeAsync(request);
}

@* Summary stats bar showing task counts *@

<div class="d-flex flex-wrap gap-3 mb-3 p-3 bg-light rounded">
    <div><strong>Total:</strong> @TotalCount</div>
    <div><strong>To Do:</strong> @ToDoCount</div>
    <div><strong>In Progress:</strong> @InProgressCount</div>
    <div><strong>Done:</strong> @DoneCount</div>
    <div class="@(OverdueCount > 0 ? "text-danger" : "")">
        <strong>Overdue:</strong> @OverdueCount
    </div>
</div>

@code {
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int ToDoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@* Search input for filtering tasks by title *@

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Search tasks by title..."
           value="@SearchText" @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}

