+    <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />
+
+    <div class="row g-3">
+        <KanbanColumn ColumnName="To Do"
+                      Tasks="FilteredToDo"
+                      CanMoveLeft="false"
+                      CanMoveRight="true"
+                      OnTaskMoved="HandleTaskMoved"
+                      OnTaskCreated="HandleTaskCreated" />
+
+        <KanbanColumn ColumnName="In Progress"
+                      Tasks="FilteredInProgress"
+                      CanMoveLeft="true"
+                      CanMoveRight="true"
+                      OnTaskMoved="HandleTaskMoved"
+                      OnTaskCreated="HandleTaskCreated" />
+
+        <KanbanColumn ColumnName="Done"
+                      Tasks="FilteredDone"
+                      CanMoveLeft="true"
+                      CanMoveRight="false"
+                      OnTaskMoved="HandleTaskMoved"
+                      OnTaskCreated="HandleTaskCreated" />
+    </div>
+}
+
+@code {
+    private List<TaskItem> allTasks = new();
+    private string searchText = "";
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    // Unfiltered column lists (for stats)
+    private List<TaskItem> ToDoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
+    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
+    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();
+
+    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);
+
+    // Filtered column lists (for display)
+    private List<TaskItem> FilteredToDo => ApplySearch(ToDoTasks);
+    private List<TaskItem> FilteredInProgress => ApplySearch(InProgressTasks);
+    private List<TaskItem> FilteredDone => ApplySearch(DoneTasks);
+
+    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
+    {
+        if (string.IsNullOrWhiteSpace(searchText))
+            return tasks;
+        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasks();
+    }
+
+    private async Task LoadTasks()
+    {
+        isLoading = true;
+        errorMessage = null;
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void HandleSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async Task HandleTaskMoved((TaskItem Task, string Direction) args)
+    {
+        var currentIndex = Array.IndexOf(Columns, args.Task.Status);
+        var newIndex = args.Direction == "left" ? currentIndex - 1 : currentIndex + 1;
+
+        if (newIndex < 0 || newIndex >= Columns.Length)
+            return;
+
+        var newStatus = Columns[newIndex];
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(args.Task.Id, newStatus);
+            // Update local state
+            var index = allTasks.FindIndex(t => t.Id == args.Task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = args.Task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to move task: {ex.Message}";
+        }
+    }
+
+    private async Task HandleTaskCreated(AddTaskForm.NewTaskRequest request)
+    {
+        var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
+        allTasks.Add(created with { Status = request.Status });
+    }
+}
+

